import smbus2
import time
import sys

# Constants for ADS1115
ADS1115_I2C_ADDRESS = 0x48
ADS1115_CONFIG_REG = 0x01
CONFIG_MUX_AIN0P_GNDN = 0x4000
CONFIG_FSR_4V096 = 0x0080
CONFIG_DATA_RATE_128SPS = 0x0000
CONFIG_COMP_QUE_DISABLE = 0x0003

# I2C bus number
I2C_BUS = 1

def swap_bytes(value):
    return (value >> 8) | (value << 8)

def readAdc(channel):
    config = CONFIG_MUX_AIN0P_GNDN | (channel << 12) | CONFIG_FSR_4V096 | CONFIG_DATA_RATE_128SPS | CONFIG_COMP_QUE_DISABLE
    bus.write_word_data(ADS1115_I2C_ADDRESS, ADS1115_CONFIG_REG, swap_bytes(config))
    while True:
        status = bus.read_byte_data(ADS1115_I2C_ADDRESS, ADS1115_CONFIG_REG)
        if status & 0x80:
            break
    adc_value = bus.read_word_data(ADS1115_I2C_ADDRESS, 0x00)
    return swap_bytes(adc_value)

def main():
    global bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
        while True:
            for channel in range(4):
                adc_value = readAdc(channel)
                print(f"Channel {channel}: {adc_value}")
            time.sleep(0.05)
    except KeyboardInterrupt:
        print("Exiting gracefully...")
    finally:
        if 'bus' in locals():
            bus.close()

if __name__ == "__main__":
    main()

