import smbus2
import logging
import signal
import sys

class ADS1015:
    def __init__(self, address=0x48, busnum=1, debug=False):
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = smbus2.SMBus(busnum)
        self.last_conversion_result = None
        self._initialize_device()

    def _initialize_device(self):
        try:
            config_register = self.bus.read_word_data(self.address, 0x01)
            if self.debug:
                logging.info(f"Config register: {config_register:04X}")
        except smbus2.SMBusError as e:
            logging.error(f"Failed to read config register: {e}")
            self.bus.close()
            sys.exit(1)

    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        try:
            config = self._build_config(channel, pga, sps, single_ended=True)
            self.bus.write_word_data(self.address, 0x01, config)
            time.sleep(0.001)  # Wait for conversion to complete
            adc_value = self.bus.read_word_data(self.address, 0x00)
            self.last_conversion_result = adc_value
            return adc_value
        except smbus2.SMBusError as e:
            logging.error(f"Failed to read ADC value: {e}")
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        try:
            config = self._build_config(channel, pga, sps, continuous=True)
            self.bus.write_word_data(self.address, 0x01, config)
        except smbus2.SMBusError as e:
            logging.error(f"Failed to start continuous conversion: {e}")

    def get_last_conversion_results(self):
        return self.last_conversion_result

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        try:
            config = self._build_config(channel, pga, sps, single_ended=True, comparator=True, active_low=active_low, traditional_mode=traditional_mode, latching=latching, num_readings=num_readings)
            lo_thresh = threshold_low & 0x0FFF
            hi_thresh = threshold_high & 0x0FFF
            self.bus.write_word_data(self.address, 0x02, lo_thresh)
            self.bus.write_word_data(self.address, 0x03, hi_thresh)
            self.bus.write_word_data(self.address, 0x01, config)
        except smbus2.SMBusError as e:
            logging.error(f"Failed to start single-ended comparator: {e}")

    def _build_config(self, channel, pga, sps, single_ended=False, continuous=False, comparator=False, active_low=True, traditional_mode=True, latching=False, num_readings=1):
        config = 0x8000  # Start bit
        config |= (channel << 12) & 0x7000  # Channel selection
        config |= (pga << 9) & 0x0E00  # PGA selection
        config |= (sps << 5) & 0x01E0  # Data rate selection
        if single_ended:
            config |= 0x0020  # Single-ended mode
        if continuous:
            config |= 0x0010  # Continuous conversion mode
        if comparator:
            config |= 0x0008  # Comparator mode
            if active_low:
                config |= 0x0004  # Active low
            if traditional_mode:
                config |= 0x0002  # Traditional mode
            if latching:
                config |= 0x0001  # Latching comparator
            config |= (num_readings << 12) & 0x7000  # Comparator num readings
        return config

    def __del__(self):
        self.bus.close()

def signal_handler(sig, frame):
    logging.info("Received signal, closing I2C bus...")
    sys.exit(0)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    adc = ADS1015(debug=True)
    adc.start_continuous_conversion(channel=0, pga=6144, sps=250)
    try:
        while True:
            result = adc.get_last_conversion_results()
            if result is not None:
                logging.info(f"ADC result: {result}")
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        adc.bus.close()

