import time
import logging
import os
import signal
import spidev
from gpiozero import LED, OutputDevice
from adafruit_dht import DHT22
from picamera2 import Picamera2
from paho.mqtt import client as mqtt_client

# Setup logging
logging.basicConfig(filename='greenhouse.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup
try:
    pump = OutputDevice(17)
    fan = OutputDevice(27)
    light = OutputDevice(22)
    led = LED(25)
except Exception as e:
    logging.error(f"GPIO setup failed: {e}")
    exit(1)

# SPI setup
try:
    spi = spidev.SpiDev()
    spi.open(0, 0)
    spi.max_speed_hz = 1000000
except Exception as e:
    logging.error(f"SPI setup failed: {e}")
    exit(1)

# DHT22 sensor setup
dht_device = None
try:
    dht_device = DHT22(4)
except Exception as e:
    logging.warning(f"DHT22 sensor setup failed: {e}")

# Camera setup
camera = Picamera2()
camera.start()

# Watchdog setup
last_activity = time.time()

def reset_watchdog():
    global last_activity
    last_activity = time.time()

def watchdog_handler(signum, frame):
    if time.time() - last_activity > 600:
        logging.error("Watchdog triggered, restarting program")
        os.execv(__file__, ["python3", __file__])

signal.signal(signal.SIGTERM, watchdog_handler)
signal.signal(signal.SIGINT, watchdog_handler)

def control_pump(command):
    if command == 'on':
        pump.on()
    elif command == 'off':
        pump.off()
    reset_watchdog()

def control_fan(command):
    if command == 'on':
        fan.on()
    elif command == 'off':
        fan.off()
    reset_watchdog()

def control_light(command):
    if command == 'on':
        light.on()
    elif command == 'off':
        light.off()
    reset_watchdog()

def set_led_status(status):
    if status == 'online':
        led.on()
    elif status == 'offline':
        led.off()
    elif status == 'error':
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
    elif status == 'synchronizing':
        for _ in range(5):
            led.on()
            time.sleep(0.2)
            led.off()
            time.sleep(0.2)
    reset_watchdog()

def read_sensor():
    global last_activity
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        last_activity = time.time()
        return temperature, humidity
    except Exception as e:
        logging.error(f"Failed to read sensor: {e}")
        return None, None

def read_adc(channel):
    try:
        adc_value = spi.xfer2([1, (8 + channel) << 4, 0])[1] & 3
        adc_value = (adc_value << 8) | spi.xfer2([0, 0])[1]
        return adc_value
    except Exception as e:
        logging.error(f"Failed to read ADC: {e}")
        return None

def main():
    while True:
        temperature, humidity = read_sensor()
        if temperature is not None and humidity is not None:
            logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
            set_led_status('online')
        else:
            set_led_status('error')

        adc_value = read_adc(0)
        if adc_value is not None:
            logging.info(f"ADC Value: {adc_value}")
        else:
            logging.error("Failed to read ADC value")

        time.sleep(300)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        pump.off()
        fan.off()
        light.off()
        led.off()
        spi.close()
        camera.stop()
        logging.info("Program terminated")

