import spidev
import time
import signal
import sys

class MCP3008:
    def __init__(self, bus=0, device=0):
        self.spi = spidev.SpiDev()
        self.spi.open(bus, device)
        self.spi.max_speed_hz = 1350000

    def read_channel(self, channel):
        adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data

    def close(self):
        self.spi.close()

def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    adc.close()
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    adc = MCP3008()
    try:
        while True:
            raw_value = adc.read_channel(0)
            voltage = (raw_value / 1023) * 3.3
            ppm = voltage * 200

            if ppm < 150:
                alert_level = "Safe"
            elif ppm < 400:
                alert_level = "Warning"
            else:
                alert_level = "Danger"

            print(f"Raw Value: {raw_value}, Voltage: {voltage:.2f}V, PPM: {ppm:.2f}, Alert: {alert_level}")

            time.sleep(0.5)
    except OSError as e:
        print(f"SPI error: {e}")
    finally:
        adc.close()

if __name__ == "__main__":
    main()

import math
from typing import Tuple, Real
from fractions import Fraction

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("Input must be a real number")

    degrees = int(degrees_decimal)
    minutes = int((degrees_decimal - degrees) * 60)
    seconds = ((degrees_decimal - degrees) * 60 - minutes) * 60

    return degrees, minutes, seconds

def number_to_exif_rational(number: Real) -> Tuple[int, int]:
    if not isinstance(number, (int, float)):
        raise ValueError("Input must be a real number")

    try:
        fraction = Fraction(number).limit_denominator(1000)
    except ValueError:
        raise ValueError("Cannot convert to a fraction")

    if not isinstance(fraction.numerator, int) or not isinstance(fraction.denominator, int):
        raise TypeError("Numerator and denominator must be integers")

    return fraction.numerator, fraction.denominator

