import RPi.GPIO as GPIO
import picamera2
import adafruit_dht
import speech_recognition as sr
import time
import os
import signal
import sys
from datetime import datetime

# Constants
GPIO_PIN_LIGHTS = 17
GPIO_PIN_SENSOR = 4
CAMERA_RESOLUTION = (640, 480)
TEMPERATURE_MIN = 15
TEMPERATURE_MAX = 35
WAKE_WORD = "Greenhouse"

# Initialize GPIO
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(GPIO_PIN_LIGHTS, GPIO.OUT)
except Exception as e:
    print(f"Failed to initialize GPIO: {e}")
    GPIO = None

# Initialize camera
try:
    camera = picamera2.PiCamera2()
    camera.start()
except Exception as e:
    print(f"Failed to initialize camera: {e}")
    camera = None

# Initialize DHT11 sensor
try:
    dht_sensor = adafruit_dht.DHT11(GPIO_PIN_SENSOR)
except Exception as e:
    print(f"Failed to initialize DHT11 sensor: {e}")
    dht_sensor = None

# Initialize speech recognition
recognizer = sr.Recognizer()
mic = sr.Microphone()

def turn_lights_on():
    if GPIO:
        GPIO.output(GPIO_PIN_LIGHTS, GPIO.HIGH)
    else:
        print("Simulated: Lights ON")

def turn_lights_off():
    if GPIO:
        GPIO.output(GPIO_PIN_LIGHTS, GPIO.LOW)
    else:
        print("Simulated: Lights OFF")

def read_temperature():
    if dht_sensor:
        try:
            temperature = dht_sensor.temperature
            if temperature is not None:
                return temperature
        except adafruit_dht.DHTError as e:
            print(f"DHT11 error: {e}")
    if GPIO:
        return None
    else:
        return (TEMPERATURE_MIN + TEMPERATURE_MAX) / 2

def take_picture():
    if camera:
        timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture(filename)
        print(f"Picture saved as {filename}")
    else:
        print("Simulated: Picture taken")

def handle_signal(signum, frame):
    print("Exiting gracefully...")
    if GPIO:
        GPIO.cleanup()
    if camera:
        camera.stop()
    sys.exit(0)

# Set up signal handlers
signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def listen_for_commands():
    with mic as source:
        recognizer.adjust_for_ambient_noise(source)
        while True:
            print("Listening for commands...")
            try:
                audio = recognizer.listen(source, timeout=5)
                command = recognizer.recognize_google(audio, language="en-US")
                print(f"Recognized command: {command}")
                if WAKE_WORD in command:
                    command = command.replace(WAKE_WORD, "").strip().lower()
                    if "turn on the lights" in command:
                        turn_lights_on()
                    elif "turn off the lights" in command:
                        turn_lights_off()
                    elif "what is the temperature" in command:
                        temperature = read_temperature()
                        if temperature is not None:
                            print(f"Current temperature: {temperature}°C")
                        else:
                            print("Failed to read temperature")
                    elif "take a picture" in command:
                        take_picture()
            except sr.UnknownValueError:
                print("Google Speech Recognition could not understand audio")
            except sr.RequestError as e:
                print(f"Could not request results from Google Speech Recognition service; {e}")

if __name__ == "__main__":
    listen_for_commands()

