    global gain
    gain = 2.0 if gain == 1.0 else 1.0

def soft_clip(x):
    return np.tanh(x)

def audio_callback(indata, outdata, frames, time, status):
    if status:
        print(status, file=sys.stderr)
    try:
        outdata[:] = gain * soft_clip(indata)
    except Exception as e:
        print(f"Audio callback error: {e}", file=sys.stderr)

def signal_handler(sig, frame):
    global audio_stream
    print("Exiting...")
    if audio_stream:
        audio_stream.stop()
        audio_stream.close()
    button.close()
    sys.exit(0)

def main():
    global audio_stream
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        audio_stream = sd.Stream(samplerate=44100, blocksize=1024, channels=1, callback=audio_callback, dtype='float32')
        audio_stream.start()
        button.when_pressed = gain_toggle
        print("Audio effects processor started. Press Ctrl+C to exit.")
        while True:
