import smbus2
import time
import signal
import sys

# Constants
I2C_ADDRESS = 0x20
I2C_BUS = 1
POLL_INTERVAL = 0.1  # 100 milliseconds

def signal_handler(sig, frame):
    print("Exiting gracefully...")
    bus.close()
    sys.exit(0)

def read_sensors():
    try:
        # Read the current state of the output port register
        sensor_states = bus.read_byte_data(I2C_ADDRESS, 0)
        return sensor_states
    except smbus2.SMBusError as e:
        print(f"I2C error: {e}")
        time.sleep(1)
        return None

def main():
    global bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except smbus2.SMBusError as e:
        print(f"Failed to initialize I2C bus: {e}")
        sys.exit(1)

    # Set all pins as inputs with internal pull-up enabled
    bus.write_byte_data(I2C_ADDRESS, 0, 0xFF)

    signal.signal(signal.SIGINT, signal_handler)

    while True:
        sensor_states = read_sensors()
        if sensor_states is not None:
            for i in range(8):
                if sensor_states & (1 << i) == 0:
                    print(f"Obstacle detected by sensor {i}")
        time.sleep(POLL_INTERVAL)

if __name__ == "__main__":
    main()

import RPi.GPIO as GPIO
import time

# Setup GPIO
GPIO.setmode(GPIO.BCM)
TRIG = 5
ECHO = 6
GPIO.setup(TRIG, GPIO.OUT)
GPIO.setup(ECHO, GPIO.IN)

def measure_distance():
    GPIO.output(TRIG, False)
    time.sleep(0.000002)
    GPIO.output(TRIG, True)
    time.sleep(0.00001)
    GPIO.output(TRIG, False)

    pulse_start = time.time()
    pulse_end = time.time()

    while GPIO.input(ECHO) == 0:
        pulse_start = time.time()
        if time.time() - pulse_start > 1:
            return None

    while GPIO.input(ECHO) == 1:
        pulse_end = time.time()
        if time.time() - pulse_start > 1:
            return None

    pulse_duration = pulse_end - pulse_start
    distance = pulse_duration * 17150
    distance = round(distance, 2)
    return distance

def classify_gesture(prev_distance, current_distance):
    if prev_distance is None or current_distance is None:
        return None
    if current_distance < prev_distance - 5:
        return 'swipe_in'
    elif current_distance > prev_distance + 5:
        return 'swipe_out'
    else:
        return 'hold'

try:
    prev_distance = None
    for _ in range(10):
        current_distance = measure_distance()
        if current_distance is None:
            print("Sensor timeout or invalid reading")
        else:
            gesture = classify_gesture(prev_distance, current_distance)
            if gesture:
                print(f"Gesture: {gesture}")
            prev_distance = current_distance
        time.sleep(0.3)

except KeyboardInterrupt:
    print("Program terminated by user")

finally:
    GPIO.cleanup()

