        if result.returncode == 0:
            temp_str = result.stdout.strip()
            if temp_str.startswith('temp=') and temp_str.endswith("'C"):
                return float(temp_str[5:-2])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired):
        logging.warning("Failed to read Pi temperature, using N/A")
    return None

def simulate_light_level():
    current_hour = datetime.now().hour
    if 6 <= current_hour < 18:
        return 600 + (1000 - 600) * (current_hour - 6) / 12
    else:
        return 100 + (300 - 100) * (current_hour - 18) / 6

def simulate_temperature():
    return 20 + (30 - 20) * random.random()

def simulate_voltage_current(light_level):
    if light_level > 300:
        return 11.5 + (12.5 - 11.5) * random.random(), 1.5 + (2.5 - 1.5) * random.random()
    else:
        return 10.0 + (11.0 - 10.0) * random.random(), 0.5 + (1.0 - 0.5) * random.random()

def log_sensor_data(light_level, temperature, voltage, current, pi_temp):
    logging.info(f"Light: {light_level:.2f} lux, Temp: {temperature:.2f}°C, Voltage: {voltage:.2f}V, Current: {current:.2f}A, Pi Temp: {pi_temp if pi_temp is not None else 'N/A'}")

def main():
    logging.info("Initializing GPIO devices...")
    try:
        light_sensor.close()
        temp_sensor.close()
    except Exception as e:
        logging.error(f"Failed to close GPIO devices: {e}")
    finally:
        light_sensor = InputDevice(17, pull_up=False, pin_factory=factory)
        temp_sensor = InputDevice(4, pull_up=False, pin_factory=factory)
        logging.info("GPIO devices initialized successfully.")

    try:
        while True:
            light_level = simulate_light_level()
            temperature = simulate_temperature()
            voltage, current = simulate_voltage_current(light_level)
            pi_temp = read_pi_temperature()

            log_sensor_data(light_level, temperature, voltage, current, pi_temp)

            if light_level < 300:
                logging.warning("Possible solar panel performance issues detected.")
            if temperature > 35:
                logging.warning("Simulated cooling system activated.")
            if pi_temp is not None and pi_temp > 75:
                logging.critical("Simulated system shutdown due to high Pi temperature.")

            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        light_sensor.close()
        temp_sensor.close()
        logging.info("GPIO devices closed.")

if __name__ == '__main__':
    main()

