import json
import random
import threading
import time
import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion

def generate_temperature(index):
    return round(19.0 + (random.random() * 7.0), 2)

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        client.connected_flag.set()
    else:
        print(f"Failed to connect, return code {rc}")

def on_publish(client, userdata, mid):
    print(f"Message {mid} published")

def publish_temperature(client, topic, num_messages):
    client.connected_flag = threading.Event()
    client.on_connect = on_connect
    client.on_publish = on_publish
    client.tls_set()
    client.connect("test.mosquitto.org", 1883, 60)
    client.loop_start()

    for i in range(num_messages):
        while not client.connected_flag.is_set():
            time.sleep(0.1)
        temp = generate_temperature(i)
        payload = json.dumps({"index": i, "temperature": temp})
        result, mid = client.publish(topic, payload)
        if result != 0:
            print(f"Failed to publish message {i}, retrying...")
        else:
            client.connected_flag.clear()
        time.sleep(1)

    client.loop_stop()
    client.disconnect()

if __name__ == "__main__":
    client = mqtt.Client(client_id="classroom_temp_publisher", callback_api_version=CallbackAPIVersion.VERSION2)
    publish_temperature(client, "classroom/temperature", 5)
    print("All messages published")
    exit(0)

