import smbus2
import time
import logging

class DHT20Sensor:
    def __init__(self):
        self.bus = None
        self.address = 0x38
        self.logger = logging.getLogger('DHT20Sensor')
        self.logger.setLevel(logging.DEBUG)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.open_bus()

    def open_bus(self):
        try:
            self.bus = smbus2.SMBus(1)
            time.sleep(0.5)
            status = self.bus.read_byte_data(self.address, 0x71)
            if (status & 0x18) != 0x18:
                self.logger.error("DHT20 sensor status check failed")
                self.bus.close()
                self.bus = None
                return False
        except smbus2.SMBusError as e:
            self.logger.error(f"Failed to open I2C bus: {e}")
            return False
        return True

    def get_temperature_and_humidity(self):
        for attempt in range(5):
            try:
                self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
                start_time = time.time()
                while time.time() - start_time < 0.1:
                    status = self.bus.read_byte_data(self.address, 0x71)
                    if not (status & 0x80):
                        break
                else:
                    self.logger.warning("DHT20 measurement timeout")
                    continue

                data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
                raw_H = (data[1] << 16) | (data[2] << 8) | data[3]
                raw_T = (data[3] << 16) | (data[4] << 8) | data[5]
                crc = data[6]

                if not self.verify_crc8(data[:6], crc):
                    self.logger.warning("DHT20 CRC check failed")
                    continue

                temperature = raw_T / 5242.88 - 50
                humidity = raw_H / 1048576 * 100
                return temperature, humidity, False
            except smbus2.SMBusError as e:
                self.logger.error(f"I2C bus error: {e}")
            except Exception as e:
                self.logger.error(f"Unexpected error: {e}")
        return None, None, True

    def verify_crc8(self, data, crc):
        crc_table = [0x00, 0x31, 0x62, 0x53, 0x94, 0xA5, 0xF6, 0xC7, 0x18, 0x29, 0x7A, 0x4B, 0xED, 0xDC, 0x8F, 0xBE]
        crc_value = 0xFF
        for byte in data:
            crc_value = crc_table[(crc_value ^ byte) & 0xFF]
        return crc_value == crc

    def __del__(self):
        self.cleanup()

    def cleanup(self):
        if self.bus:
            self.bus.close()
            self.bus = None

# Example usage:
if __name__ == "__main__":
    sensor = DHT20Sensor()
    if sensor.open_bus():
        temperature, humidity, crc_error = sensor.get_temperature_and_humidity()
        if crc_error:
            print("CRC error occurred during measurement.")
        else:
            print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
    else:
        print("Failed to initialize DHT20 sensor.")

