import RPi.GPIO as GPIO
import time
import datetime

DHT_PIN = 4

def read_dht22():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.OUT)
    try:
        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.018)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.00004)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        start_time = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() - start_time > 0.02:
                return None, None

        data = []
        while len(data) < 40:
            start_time = time.time()
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() - start_time > 0.00008:
                    return None, None
            pulse_start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() - pulse_start > 0.00008:
                    return None, None
            pulse_duration = time.time() - pulse_start
            if pulse_duration > 0.000026:
                data.append(0)
            else:
                data.append(1)

        humidity_high = (data[0] << 8) | data[1]
        humidity_low = (data[2] << 8) | data[3]
        temperature_high = (data[4] << 8) | data[5]
        temperature_low = (data[6] << 8) | data[7]
        checksum = (data[8] << 8) | data[9]

        if checksum != (humidity_high + humidity_low + temperature_high + temperature_low) & 0xFF:
            return None, None

        humidity = humidity_high + humidity_low / 10.0
        temperature = temperature_high + temperature_low / 10.0
        if data[11] & 0x80:
            temperature = -temperature

        return temperature, humidity
    except Exception as e:
        print(f"Error reading DHT22: {e}")
        return None, None
    finally:
        GPIO.cleanup()

def main():
    try:
        with open('humidity_log.txt', 'a') as log_file:
            while True:
                temperature, humidity = read_dht22()
                if temperature is not None and humidity is not None:
                    log_file.write(f"{datetime.datetime.now()}, {temperature}, {humidity}\n")
                    log_file.flush()
                time.sleep(10)
    except KeyboardInterrupt:
        print("Program interrupted by user")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

