class DHT20Sensor:
    def __init__(self):
        self.bus = None
        try:
            self.bus = smbus2.SMBus(1)
            status = self.bus.read_byte_data(0x38, 0x71)
            if status != 0x00:
                logging.error("DHT20 sensor not present or not ready")
                self.bus = None
        except smbus2.SMBusError as e:
            logging.error(f"Failed to open I2C bus: {e}")
            self.bus = None

    def measure(self):
        if self.bus is None:
            return None, None, True

        try:
            self.bus.write_i2c_block_data(0x38, 0xAC, [0x33, 0x00])
            start_time = time.time()
            while True:
                status = self.bus.read_byte_data(0x38, 0x71)
                if status & 0x80 == 0:
                    break
                if time.time() - start_time > 0.1:
                    logging.error("DHT20 measurement timed out")
                    return None, None, True
                time.sleep(0.01)

            data = self.bus.read_i2c_block_data(0x38, 0x71, 7)
            crc = self.crc8(data[:-1])
            if crc != data[6]:
                logging.error("CRC error in DHT20 data")
                return None, None, True

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]
            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return temperature, humidity, False
        except smbus2.SMBusError as e:
            logging.error(f"DHT20 I2C error: {e}")
            return None, None, True

    def crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
        return crc & 0xFF

    def __del__(self):
        if self.bus is not None:
            self.bus.close()

