import RPi.GPIO as GPIO
import time
import random
import logging

# Setup logging
logging.basicConfig(filename='greenhouse_vent.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERVO_PIN_1 = 17
SERVO_PIN_2 = 18
PWM_FREQ = 50
DUTY_CYCLE_MAP = {0: 2.5, 90: 7.5, 180: 12.5}
FAILURE_RATE = 0.1
CONSECUTIVE_FAILURES = 3

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(SERVO_PIN_1, GPIO.OUT)
GPIO.setup(SERVO_PIN_2, GPIO.OUT)

# Initialize PWM
pwm1 = GPIO.PWM(SERVO_PIN_1, PWM_FREQ)
pwm2 = GPIO.PWM(SERVO_PIN_2, PWM_FREQ)
pwm1.start(0)
pwm2.start(0)

def set_servo_angle(pwm, angle):
    duty_cycle = DUTY_CYCLE_MAP[angle]
    pwm.ChangeDutyCycle(duty_cycle)
    time.sleep(0.1)
    pwm.ChangeDutyCycle(0)

def simulate_temperature():
    return random.randint(15, 35)

def move_servo(pwm, angle):
    current_angle = 0
    step = 5
    if angle > current_angle:
        for i in range(current_angle, angle + 1, step):
            set_servo_angle(pwm, i)
    else:
        for i in range(current_angle, angle - 1, -step):
            set_servo_angle(pwm, i)

def main():
    servo1_failures = 0
    servo2_failures = 0
    current_servo = pwm1

    try:
        while True:
            temperature = simulate_temperature()
            logging.info(f"Temperature: {temperature}°C")

            if temperature < 20:
                target_angle = 0
            elif temperature < 25:
                target_angle = 45
            elif temperature < 30:
                target_angle = 90
            elif temperature < 35:
                target_angle = 135
            else:
                target_angle = 180

            logging.info(f"Target angle: {target_angle}°")

            try:
                move_servo(current_servo, target_angle)
            except Exception as e:
                logging.error(f"Failed to move servo: {e}")
                if current_servo == pwm1:
                    servo1_failures += 1
                else:
                    servo2_failures += 1

                if servo1_failures >= CONSECUTIVE_FAILURES:
                    logging.info("Switching to servo2 permanently")
                    current_servo = pwm2
                    servo1_failures = 0
                    servo2_failures = 0

            time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user")

    finally:
        pwm1.stop()
        pwm2.stop()
        GPIO.cleanup()
        logging.info("GPIO and PWM resources released")

if __name__ == "__main__":
    main()

