import smbus2
import time
import logging
from contextlib import contextmanager

class DHT20:
    def __init__(self, bus=1, address=0x38):
        self.bus = bus
        self.address = address
        self.last_read_time = 0
        self.last_temperature = None
        self.last_humidity = None
        self.last_error = None

    def begin(self):
        try:
            self.i2c = smbus2.SMBus(self.bus)
            time.sleep(0.5)
            status = self.i2c.read_byte_data(self.address, 0x71)
            if (status & 0x18) != 0x18:
                logging.error(f"Invalid status register: {status:02X}")
                return False
            return True
        except OSError as e:
            logging.error(f"Failed to open I2C bus: {e}")
            return False

    def measure(self):
        for attempt in range(5):
            try:
                self.i2c.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
                for _ in range(10):
                    status = self.i2c.read_byte_data(self.address, 0x71)
                    if status & 0x80 == 0:
                        break
                    time.sleep(0.08)
                else:
                    continue  # break not taken, retry

                data = self.i2c.read_i2c_block_data(self.address, 0x71, 7)
                crc = self.calculate_crc8(data[:-1])
                if crc != data[-1]:
                    continue  # CRC mismatch, retry

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
                humidity = humidity_raw / (1 << 20) * 100
                temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
                temperature = temperature_raw / (1 << 19) * 200 - 50

                self.last_temperature = temperature
                self.last_humidity = humidity
                self.last_error = None
                return temperature, humidity, False
            except OSError as e:
                if e.errno == 5:  # EIO: Input/output error
                    logging.warning(f"Transient I2C error: {e}")
                else:
                    logging.error(f"Failed to measure: {e}")
                    self.last_error = e
        return None, None, True

    def calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
        return crc & 0xFF

    def get_temperature_and_humidity(self):
        current_time = time.time()
        if current_time - self.last_read_time < 2:
            return self.last_temperature, self.last_humidity, False
        self.last_read_time = current_time
        return self.measure()

    def close(self):
        if hasattr(self, 'i2c'):
            self.i2c.close()

    @contextmanager
    def managed(self):
        try:
            if not self.begin():
                raise Exception("DHT20 initialization failed")
            yield self
        finally:
            self.close()

def demo():
    try:
        with DHT20().managed() as dht20:
            while True:
                temp, humidity, error = dht20.get_temperature_and_humidity()
                if error:
                    print("Measurement failed")
                else:
                    print(f"Temperature: {temp:.2f}°C, Humidity: {humidity:.2f}%")
                time.sleep(1)
    except (KeyboardInterrupt, SystemExit):
        print("Demo interrupted")
    except Exception as e:
        print(f"Demo failed: {e}")

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    demo()

