import time

def read_bme280(bus, address, register):
    try:
        return bus.read_byte_data(address, register)
    except OSError as e:
        print(f"I2C error: {e}")
        return None

def read_bme280_word(bus, address, register):
    try:
        msb = bus.read_byte_data(address, register)
        lsb = bus.read_byte_data(address, register + 1)
        return (msb << 8) | lsb
    except OSError as e:
        print(f"I2C error: {e}")
        return None

def read_bme280_signed_word(bus, address, register):
    try:
        msb = bus.read_byte_data(address, register)
        lsb = bus.read_byte_data(address, register + 1)
        value = (msb << 8) | lsb
        return value if value < 32768 else value - 65536
    except OSError as e:
        print(f"I2C error: {e}")
        return None

def read_bme280_calib(bus, address):
    calib = {}
    calib['dig_H1'] = read_bme280(bus, address, 0xA1)
    calib['dig_H2'] = read_bme280_signed_word(bus, address, 0xE1)
    calib['dig_H3'] = read_bme280(bus, address, 0xE3)
    calib['dig_H4'] = read_bme280_signed_word(bus, address, 0xE4) & 0xFF
    calib['dig_H5'] = (read_bme280_signed_word(bus, address, 0xE4) >> 8) & 0x0F
    calib['dig_H6'] = read_bme280_signed_word(bus, address, 0xE5)
    return calib

def calculate_humidity(dig_H1, dig_H2, dig_H3, dig_H4, dig_H5, dig_H6, raw_humidity):
    var1 = ((raw_humidity >> 3) - (dig_H4 << 1)) * (dig_H5 >> 2)
    var2 = ((raw_humidity >> 4) - dig_H6) * ((raw_humidity >> 4) - dig_H6)
    var2 = (var2 >> 12) * dig_H3
    var1 = var1 + var2
    var1 = (var1 * 5) >> 1
    if var1 > 0x7FFFFFFF:
        var1 = (var1 >> 1) - (dig_H1 << 4)
    humidity = (var1 >> 12)
    return max(0, min(100, humidity))

def classify_humidity(humidity):
    if humidity < 30:
        return "too_dry"
    elif humidity < 40:
        return "dry"
    elif humidity < 60:
        return "comfortable"
    else:
        return "too_humid"

def main():
    bus = smbus2.SMBus(1)
    address = 0x76

    calib = read_bme280_calib(bus, address)
    if not all(calib.values()):
        print("Failed to initialize BME280 sensor.")
        bus.close()
        return

    bus.write_byte_data(address, 0xF2, 0x01)
    bus.write_byte_data(address, 0xF4, 0x3F)

    for _ in range(5):
        raw_humidity = read_bme280_word(bus, address, 0xFD)
        if raw_humidity is not None:
            humidity = calculate_humidity(calib['dig_H1'], calib['dig_H2'], calib['dig_H3'], calib['dig_H4'], calib['dig_H5'], calib['dig_H6'], raw_humidity)
            band = classify_humidity(humidity)
            timestamp = datetime.datetime.now().isoformat()
            print(f"{timestamp} - Humidity: {humidity:.2f}% - Band: {band}")
        time.sleep(2)

    bus.close()

if __name__ == "__main__":
