        temperature = get_cpu_temperature()
        set_fan_speed(temperature)
        time.sleep(5)
except KeyboardInterrupt:
    pass
finally:
    if fan:
        fan.close()
    mqtt_client.disconnect()
    mqtt_client.loop_stop()

