except PinFactoryNoPinError:
    print("Warning: PWMOutputDevice initialization failed. Running in degraded mode.")
    fan = None

# MQTT setup
mqtt_client = mqtt.Client()
mqtt_client.connect("mqtt.eclipse.org", 1883, 60)

def get_cpu_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, check=True)
        return float(result.stdout.split('=')[1].split('.')[0])
    except subprocess.CalledProcessError as e:
        print(f"Error: {e}")
        return None

def set_fan_speed(temperature):
    if temperature is None:
        return
    if temperature > 70:
        duty_cycle = 100
    elif temperature > 60:
        duty_cycle = 85
    elif temperature > 50:
        duty_cycle = 70
    elif temperature > 40:
        duty_cycle = 50
    elif temperature > 32:
        duty_cycle = 25
    elif temperature > 25:
        duty_cycle = 15
    else:
        duty_cycle = 0
    if fan:
        fan.value = duty_cycle / 100
    print(f"CPU Temp: {temperature}°C, Fan Speed: {duty_cycle}%")

def on_mqtt_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe("home/temperature")

def on_mqtt_message(client, userdata, msg):
    try:
        temperature = float(msg.payload.decode())
        set_fan_speed(temperature)
    except ValueError:
        print("Invalid temperature data received")

mqtt_client.on_connect = on_mqtt_connect
mqtt_client.on_message = on_mqtt_message

def signal_handler(sig, frame):
    print("Exiting...")
    if fan:
        fan.close()
    mqtt_client.disconnect()
    mqtt_client.loop_stop()
    exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

mqtt_client.loop_start()

try:
    while True:
        temperature = get_cpu_temperature()
        set_fan_speed(temperature)
        time.sleep(5)
except KeyboardInterrupt:
    pass
finally:
    if fan:
        fan.close()
    mqtt_client.disconnect()
    mqtt_client.loop_stop()
```

This script sets up a Raspberry Pi to control a 4-wire PWM fan using gpiozero's PWMOutputDevice. It reads the CPU temperature every 5 seconds and adjusts the fan speed based on the temperature. The script also includes MQTT functionality to receive temperature data from an external source. It handles errors gracefully, logs warnings, and ensures that hardware resources are released cleanly on exit.

