import RPi.GPIO as GPIO
import threading
import time
import signal
import sys
import os

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.cleanup()

# Define DOG class for data transfer
class DOG:
    def __init__(self):
        self.data = ""

    def send(self, data_string):
        self.data = data_string

    def receive(self):
        data = self.data
        self.data = ""
        return data

DOG = DOG()

# Global variables
log_file = None
receive_thread = None
running = False

def receive_thread_func():
    global running
    while running:
        data = DOG.receive()
        if data:
            try:
                log_file.write(data + '\n')
                log_file.flush()
            except IOError as e:
                print(f"Error writing to log file: {e}", file=sys.stderr)
        time.sleep(0.1)

def signal_handler(sig, frame):
    global running
    print("Exiting...")
    running = False
    GPIO.cleanup()
    if log_file:
        log_file.close()
    if receive_thread:
        receive_thread.join()
    sys.exit(0)

def start(filename):
    global log_file, receive_thread, running
    if log_file:
        print("Server is already running.")
        return
    try:
        log_file = open(filename, 'a')
    except IOError as e:
        print(f"Error opening log file: {e}", file=sys.stderr)
        return
    running = True
    receive_thread = threading.Thread(target=receive_thread_func)
    receive_thread.start()
    print(f"Server started. Logging to {filename}")

def stop():
    global running
    if not running:
        print("Server is not running.")
        return
    running = False
    receive_thread.join()
    if log_file:
        log_file.close()
    log_file = None
    print("Server stopped.")

def help_command(command=None):
    if command:
        if command == "start":
            print("start <filename> - Creates a file and starts the logging thread.")
        elif command == "stop":
            print("stop - Stops the server and the receive thread.")
        elif command == "help":
            print("help [command] - Displays help.")
        elif command == "display":
            print("display - Prints the contents of the log file.")
        elif command == "send":
            print("send <data> - Sends data using DOG.send().")
        elif command == "write":
            print("write <data> - Writes data directly to the log file with a newline character.")
        elif command == "exit":
            print("exit - Stops the server, cleans up GPIO, and exits.")
        else:
            print(f"Unknown command: {command}")
    else:
        print("Available commands:")
        print("start <filename>")
        print("stop")
        print("help [command]")
        print("display")
        print("send <data>")
        print("write <data>")
        print("exit")

def display():
    global log_file
    if not log_file:
        print("Server is not running.")
        return
    try:
        log_file.seek(0)
        print(log_file.read())
    except IOError as e:
        print(f"Error reading log file: {e}", file=sys.stderr)

def send(data):
    DOG.send(data)
    print(f"Sent data: {data}")

def write(data):
    global log_file
    if not log_file:
        print("Server is not running.")
        return
    try:
        log_file.write(data + '\n')
        log_file.flush()
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while True:
        command = input("Enter command: ").strip().split()
        if not command:
            continue
        cmd = command[0]
        args = command[1:]

        if cmd == "start":
            if len(args) != 1:
                print("Usage: start <filename>")
            else:
                start(args[0])
        elif cmd == "stop":
            stop()
        elif cmd == "help":
            if args:
                help_command(args[0])
            else:
                help_command()
        elif cmd == "display":
            display()
        elif cmd == "send":
            if not args:
                print("Usage: send <data>")
            else:
                send(' '.join(args))
        elif cmd == "write":
            if not args:
                print("Usage: write <data>")
            else:
                write(' '.join(args))
        elif cmd == "exit":
            stop()
            GPIO.cleanup()
            sys.exit(0)
        else:
            print(f"Unknown command: {cmd}")

if __name__ == "__main__":
    main()

