from gpiozero import LED
from gpiozero.pins.pigpio import PiGPIOFactory

# Hardcoded sentiment lexicon
vader_lexicon = {
    'good': 0.8, 'great': 0.9, 'happy': 0.7, 'excited': 0.6, 'love': 0.95,
    'bad': -0.8, 'terrible': -0.9, 'sad': -0.7, 'angry': -0.6, 'hate': -0.95,
    'okay': 0.0, 'fine': 0.0, 'meh': 0.0, 'goodbye': -0.1, 'hello': 0.1,
    'yes': 0.2, 'no': -0.2, 'maybe': 0.0, 'sure': 0.1, 'okay': 0.0
}

# Initialize GPIO if available
led_green = None
led_red = None
gpio_factory = None
try:
    gpio_factory = PiGPIOFactory()
    led_green = LED(17, pin_factory=gpio_factory)
    led_red = LED(18, pin_factory=gpio_factory)
    led_green.off()
    led_red.off()
except ImportError:
    pass

def cleanup_gpio():
    if led_green:
        led_green.close()
    if led_red:
        led_red.close()
    if gpio_factory:
        gpio_factory.close()

atexit.register(cleanup_gpio)

def sentiment_analysis(sentence):
    words = sentence.lower().split()
    total_score = 0.0
    count = 0
    for word in words:
        if word in vader_lexicon:
            total_score += vader_lexicon[word]
            count += 1
    if count == 0:
        return 0.0
    average_score = total_score / count
    return average_score

def classify_sentiment(score):
    if score > 0.2:
        return 'Positive'
    elif score < -0.2:
        return 'Negative'
    else:
        return 'Neutral'

def control_leds(sentiment):
    if sentiment == 'Positive':
        led_green.on()
        led_red.off()
        time.sleep(2)
        led_green.off()
    elif sentiment == 'Negative':
        led_green.off()
        led_red.on()
        time.sleep(2)
        led_red.off()

def main():
    try:
        sentence = input("Enter a sentence: ")
        score = sentiment_analysis(sentence)
        sentiment = classify_sentiment(score)
        print(f"Sentiment: {sentiment}")
        control_leds(sentiment)
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)

if __name__ == "__main__":
