import logging
import signal
import time
import zmq
from gpiozero import PWMOutputDevice, OutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory

class PIDHandler:
    def __init__(self, pwm=True):
        self.pwm = pwm
        self.last_msg = time.time()
        self.global_err_state = False
        self.factory = PiGPIOFactory()
        self.error_output = None

        try:
            if self.pwm:
                self.error_output = PWMOutputDevice(12, frequency=1000, initial_value=0.0, pin_factory=self.factory)
            else:
                self.error_output = OutputDevice(10, pin_factory=self.factory)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.cleanup()
            raise

        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def update_error_output(self):
        if self.error_output:
            self.error_output.value = 1.0 if self.global_err_state else 0.0

    def set_error_output(self, state: bool):
        if self.error_output:
            self.error_output.value = 1.0 if state else 0.0

    def cleanup(self, signum=None, frame=None):
        if self.error_output:
            self.error_output.close()
        logging.info("GPIO resources released.")

    def handle_message(self):
        context = zmq.Context()
        socket = context.socket(zmq.SUB)
        socket.connect("tcp://localhost:5555")
        socket.setsockopt_string(zmq.SUBSCRIBE, "")

        while True:
            try:
                message = socket.recv_string(zmq.NOBLOCK)
                self.last_msg = time.time()
                # Process subscription callbacks here
                logging.info(f"Received message: {message}")
            except zmq.error.Again:
                if time.time() - self.last_msg > 20:
                    self.set_error_output(True)
                    logging.warning("No data received for 20 seconds, setting error output.")
                time.sleep(0.1)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    pid_handler = PIDHandler(pwm=True)
    pid_handler.handle_message()

