import pigpio
import time

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not (0 <= pin_number <= 31):
            raise ValueError("Invalid pin number. Must be between 0 and 31.")
        if initial_value not in (0, 1):
            raise ValueError("Invalid initial value. Must be 0 or 1.")

        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise ConnectionError("Unable to connect to pigpio daemon.")

        self.pi.set_mode(pin_number, pigpio.OUTPUT)
        self.pi.write(pin_number, initial_value)
        self.pin_number = pin_number

    def set_value(self, value: int):
        if value not in (0, 1):
            raise ValueError("Invalid value. Must be 0 or 1.")
        try:
            self.pi.write(self.pin_number, value)
        except pigpio.Error as e:
            print(f"Error setting pin value: {e}")

    def shutdown(self):
        try:
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
        except pigpio.Error as e:
            print(f"Error setting pin mode to INPUT: {e}")
        finally:
            self.pi.stop()

    def __del__(self):
        self.shutdown()

if __name__ == '__main__':
    pin = OutputPin(17, 0)
    try:
        for _ in range(10):
            pin.set_value(1 - pin.pi.read(17))
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        pin.shutdown()

