import time
import pigpio
from adafruit_tsl2561 import TSL2561
import board
import busio

def clamp(value, min_val, max_val):
    return max(min_val, min(value, max_val))

def main():
    try:
        # Initialize I2C
        i2c = busio.I2C(board.SCL, board.SDA)
        # Initialize TSL2561 sensor
        sensor = TSL2561(i2c, address=0x39)
        sensor.enable_auto_gain = True

        # Initialize pigpio
        pi = pigpio.pi()
        if not pi.connected:
            raise Exception("Failed to connect to pigpio daemon")

        # Set up GPIO18 as hardware PWM at 1000 Hz
        pi.set_mode(18, pigpio.OUTPUT)
        pi.set_PWM_frequency(18, 1000)

        try:
            while True:
                try:
                    lux = sensor.lux
                    if lux is None:
                        raise ValueError("Lux reading is None")
                except Exception as e:
                    print(f"Warning: Failed to read lux, setting LED duty cycle to 0. Error: {e}")
                    pi.set_PWM_dutycycle(18, 0)
                else:
                    duty_cycle = clamp(int(lux / 10), 0, 100)
                    pi.set_PWM_dutycycle(18, duty_cycle)
                time.sleep(1)
        except KeyboardInterrupt:
            print("Exiting on keyboard interrupt")
        finally:
            pi.set_PWM_dutycycle(18, 0)
            pi.stop()
            print("Cleanup complete")

    except Exception as e:
        print(f"Error: {e}")
        exit(1)

if __name__ == "__main__":
    main()

