import time
from gpiozero import InputDevice
from signal import pause
from threading import Thread

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce_time=0.005):
        self.clk = InputDevice(clk_pin, pull_up=True, bounce_time=debounce_time)
        self.dt = InputDevice(dt_pin, pull_up=True, bounce_time=debounce_time)
        self.callback = callback
        self.counter = 0
        self.last_clk_state = self.clk.is_active
        self.running = True
        self.thread = Thread(target=self._monitor)
        self.thread.start()

    def _monitor(self):
        while self.running:
            current_clk_state = self.clk.is_active
            if current_clk_state != self.last_clk_state:
                dt_state = self.dt.is_active
                if dt_state != current_clk_state:
                    self.counter += 1
                else:
                    self.counter -= 1
                self.last_clk_state = current_clk_state
                if self.callback and callable(self.callback):
                    try:
                        self.callback(self.counter)
                    except Exception as e:
                        print(f"Callback error: {e}")
            time.sleep(0.001)

    def cleanup(self):
        self.running = False
        self.thread.join()
        self.clk.close()
        self.dt.close()

    def __del__(self):
        self.cleanup()

if __name__ == "__main__":
    def on_rotate(counter):
        print(f"Rotated {counter} times")

    encoder = RotaryEncoder(17, 18, callback=on_rotate)

    try:
        pause()
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        encoder.cleanup()

