url = "http://localhost:8000/quality"

# Function to handle button press
def on_button_press():
    return False, 1

# Function to handle button release
def on_button_release():
    return True, 0

# Function to submit the report
def submit_report(passed, defect_count):
    report = {
        "part_id": "PART-204",
        "passed": passed,
        "defect_count": defect_count
    }
    headers = {"Content-Type": "application/json"}
    try:
        response = requests.post(url, data=json.dumps(report), headers=headers, timeout=5)
        response.raise_for_status()
        print(f"HTTP Status Code: {response.status_code}")
    except requests.exceptions.Timeout:
        print("Network error: Timeout")
    except requests.exceptions.ConnectionError:
        print("Network error: Connection refused")
    except requests.exceptions.DNSLookupError:
        print("Network error: DNS failure")

# Function to handle cleanup on exit
def cleanup(signum, frame):
    button.close()
    sys.exit(0)

# Register the cleanup function to handle exit signals
signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

# Main loop
try:
    last_state = None
    while True:
        current_state = button.is_pressed
        if current_state != last_state:
            if current_state:
                passed, defect_count = on_button_press()
            else:
                passed, defect_count = on_button_release()
            submit_report(passed, defect_count)
            last_state = current_state
        button.wait_for_release()
        button.wait_for_press()
