class Fuchikoma:
    def __init__(self):
        try:
            self.pca = PCA9685(busio.I2C(board.SCL, board.SDA), address=0x40)
            self.pca.frequency = 60
            self.claw = 0
            self.lock = 1
            self.water_gun = 2
            self.servo_min_pulse = 150
            self.servo_max_pulse = 600
            self.servo_angle_range = 77
            atexit.register(self.cleanup)
        except (ValueError, OSError) as e:
            print(f"PCA9685 not found: {e}")
            exit(1)

    def move_servo(self, servo_name, angle, delay=0.029):
        if servo_name not in ['claw', 'lock', 'water_gun']:
            raise ValueError(f"Invalid servo name: {servo_name}")
        if not (-self.servo_angle_range <= angle <= self.servo_angle_range):
            raise ValueError(f"Angle out of range: {angle}")
        channel = getattr(self, servo_name)
        pulse_width = self.angle_to_pulse(angle)
        self.pca.channels[channel].duty_cycle = self.pulse_to_duty_cycle(pulse_width)
        time.sleep(delay)
        self.pca.channels[channel].duty_cycle = 0

    def angle_to_pulse(self, angle):
        return int(self.servo_min_pulse + (angle / self.servo_angle_range) * (self.servo_max_pulse - self.servo_min_pulse))

    def pulse_to_duty_cycle(self, pulse_width):
        return int((pulse_width / 20000) * 65535)

    def bite(self):
        self.move_servo('claw', -75)

    def open_claw(self):
        self.move_servo('claw', 75)

    def lock(self):
        self.move_servo('lock', 75)

    def unlock(self):
        self.move_servo('lock', -75)

