        self.move_servo('water_gun', -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo('water_gun', 75)

    def cleanup(self):
        for channel in range(16):
            self.pca.channels[channel].duty_cycle = 0
        self.pca.deinit()

if __name__ == "__main__":
    fuchikoma = Fuchikoma()
    try:
        fuchikoma.bite()
        time.sleep(1)
        fuchikoma.open_claw()
        time.sleep(1)
        fuchikoma.lock()
        time.sleep(1)
        fuchikoma.unlock()
        time.sleep(1)
        fuchikoma.shoot()
    except KeyboardInterrupt:
        print("KeyboardInterrupt received, cleaning up...")
