import socket
import signal
import sys
import json
import time
import logging
from gpiozero import LED
from pyserial import Serial, SerialException
from smbus2 import SMBus, SMBusException
from adafruit_gps import GPS, GPSParser

# Setup logging
logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
GPS_I2C_ADDRESS = 0x42
GPS_UART_PORT = '/dev/ttyS0'
GPS_UART_BAUDRATE = 9600
TCP_HOST = '127.0.0.1'
TCP_PORT = 9099
TCP_TIMEOUT = 2

# Global variables
gps_connection = None
gps_available = False
tracking_state = 'stopped'
led = LED(17)  # Example GPIO pin for LED control

def read_gps_position():
    global gps_connection, gps_available
    if not gps_available:
        return None, None
    try:
        gps_connection.send(b'\x01')  # Request position
        time.sleep(0.1)
        data = gps_connection.read(100)
        if data:
            return data.decode().split(',')
        else:
            return None, None
    except (SerialException, SMBusException) as e:
        logging.error(f"Failed to read GPS position: {e}")
        return None, None

def handle_command(command):
    global tracking_state
    if command == 'start':
        tracking_state = 'running'
        led.on()
    elif command == 'stop':
        tracking_state = 'stopped'
        led.off()
    elif command == 'report':
        lat, lon = read_gps_position()
        if lat and lon:
            return json.dumps({'lat': lat, 'lon': lon})
        else:
            return json.dumps({'lat': 'N/A', 'lon': 'N/A'})
    else:
        return json.dumps({'error': 'Invalid command'})

def main():
    global gps_connection, gps_available
    try:
        # Setup TCP server
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.settimeout(TCP_TIMEOUT)
        server_socket.bind((TCP_HOST, TCP_PORT))
        server_socket.listen(1)
        logging.info(f"Listening on {TCP_HOST}:{TCP_PORT}")

        # Setup GPS
        try:
            gps_connection = Serial(GPS_UART_PORT, GPS_UART_BAUDRATE, timeout=1)
            gps_available = True
            logging.info("GPS connected via UART")
        except SerialException:
            try:
                gps_connection = SMBus(1)
                gps_connection.write_byte(GPS_I2C_ADDRESS, 0x01)  # Initialize GPS
                gps_available = True
                logging.info("GPS connected via I2C")
            except SMBusException:
                logging.error("Failed to connect to GPS")
                gps_available = False

        while True:
            try:
                client_socket, addr = server_socket.accept()
                logging.info(f"Connection from {addr}")
                data = client_socket.recv(1024).decode().strip()
                if data:
                    response = handle_command(data)
                    client_socket.sendall(response.encode())
                client_socket.close()
            except socket.timeout:
                logging.info("No connection received within timeout")
            except Exception as e:
                logging.error(f"Error handling client: {e}")
                client_socket.close()

    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        if gps_connection:
            if isinstance(gps_connection, Serial):
                gps_connection.close()
            elif isinstance(gps_connection, SMBus):
                gps_connection.close()
        server_socket.close()
        logging.info("Shutting down")

def signal_handler(sig, frame):
    logging.info("Received signal, shutting down")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

