import smbus2
import time
from gpiozero import LED, Buzzer
from signal import signal, SIGINT
from sys import exit

def initialize_hardware():
    try:
        i2c = smbus2.SMBus(1)
        led = LED(21)
        buzzer = Buzzer(20)
        return i2c, led, buzzer
    except Exception as e:
        print(f"Error initializing hardware: {e}")
        exit(1)

def read_who_am_i(i2c):
    try:
        return i2c.read_byte_data(0x18, 0x0F)
    except smbus2.SMBusError as e:
        print(f"I2C read error: {e}")
        return None

def configure_lis3dh(i2c):
    try:
        i2c.write_byte_data(0x18, 0x20, 0x57)
        time.sleep(0.1)
        i2c.write_byte_data(0x18, 0x23, 0x00)
        time.sleep(0.1)
    except smbus2.SMBusError as e:
        print(f"I2C write error: {e}")

def read_acceleration(i2c):
    try:
        data = i2c.read_i2c_block_data(0x18, 0x28, 2)
        return (data[0] | (data[1] << 8)) >> 4
    except smbus2.SMBusError as e:
        print(f"I2C read error: {e}")
        return None

def main():
    i2c, led, buzzer = initialize_hardware()
    who_am_i = read_who_am_i(i2c)
    if who_am_i is None or who_am_i != 0x33:
        print("LIS3DH not found or communication error.")
        exit(1)
    configure_lis3dh(i2c)

    def signal_handler(sig, frame):
        led.off()
        buzzer.off()
        i2c.close()
        print("Exiting gracefully.")
        exit(0)

    signal(SIGINT, signal_handler)

    while True:
        acceleration = read_acceleration(i2c)
        if acceleration is not None:
            g = acceleration / 16384.0
            print(f"X-axis acceleration: {g:.4f} g")
            led.value = abs(g) > 0.3
            buzzer.value = abs(g) > 0.7
        time.sleep(0.1)

if __name__ == "__main__":
    main()

