from contextlib import contextmanager

@contextmanager
def managed_led(pin):
    led = LED(pin)
    try:
        yield led
    finally:
        led.off()

def simulate_moisture_reading():
    return random.randint(0, 100)

def main():
    moisture_threshold = 30
    led_pin = 23

    with managed_led(led_pin) as led:
        for _ in range(3):
            moisture_level = simulate_moisture_reading()
            print(f"Moisture level: {moisture_level}%")
            if moisture_level < moisture_threshold:
                led.on()
                time.sleep(2)
                led.off()
                print("Watering complete.")
            else:
                print("Moisture is sufficient.")
            time.sleep(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("Clean shutdown.")

