import RPi.GPIO as GPIO
import time
from datetime import datetime

# Constants
PIR_PIN = 4
FEEDING_TIME_START = 7 * 3600  # 7:00 AM in seconds since midnight
FEEDING_TIME_END = 8 * 3600  # 8:00 AM in seconds since midnight
COOLDOWN_TIME = 60  # 60 seconds cooldown period

# Global variables
last_feeding_time = None

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

def cleanup_gpio():
    GPIO.cleanup()

def is_feeding_time(now):
    current_time = now.hour * 3600 + now.minute * 60 + now.second
    return FEEDING_TIME_START <= current_time < FEEDING_TIME_END or \
           FEEDING_TIME_END <= current_time < FEEDING_TIME_START + 24 * 3600

def log_event(message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - {message}")

def main():
    try:
        setup_gpio()
        last_motion_time = None
        while True:
            now = datetime.now()
            motion_detected = GPIO.input(PIR_PIN) == GPIO.HIGH
            if motion_detected:
                if last_motion_time is None or (now - last_motion_time).total_seconds() >= 1:
                    log_event("Motion detected")
                    if is_feeding_time(now):
                        if last_feeding_time is None or (now - last_feeding_time).total_seconds() >= COOLDOWN_TIME:
                            log_event(f"Feeding initiated at {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
                            last_feeding_time = now
                        else:
                            log_event("Not feeding time or recently fed.")
                    else:
                        log_event("Not feeding time or recently fed.")
                    last_motion_time = now
            time.sleep(1)
    except KeyboardInterrupt:
        log_event("Exiting program...")
    except Exception as e:
        log_event(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

