                    last_motion_time = now
            time.sleep(1)
    except KeyboardInterrupt:
        log_event("Exiting program...")
    except Exception as e:
        log_event(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()
