        if not isinstance(freq, int) or freq <= 0:
            raise MotorError("Invalid frequency")
        rc = self.pi.set_PWM_frequency(self.pin, freq)
        if rc != 0:
            raise MotorError(f"Failed to set frequency: {rc}")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or not (0 <= duty <= 255):
