        rc = self.pi.set_PWM_dutycycle(self.pin, duty)
        if rc != 0:
            raise MotorError(f"Failed to set duty cycle: {rc}")

    def stop(self):
        self.pi.set_PWM_dutycycle(self.pin, 0)

    def __del__(self):
        self.stop()
        self.close()

    def close(self):
        self.pi.stop()

