import serial
import serial.tools.list_ports
import signal
import sys
import time
from pymodbus.client.sync import ModbusSerialClient as ModbusClient
from pymodbus.exceptions import ModbusIOException, ModbusSerialException
import logging

# Setup logging
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

# Modbus register map
REGISTER_MAP = {
    'CONTROL': {'R/W': 'W', 'Register': 0x3100, 'functioncode': 6, 'Value': {'Stop': 0x0006, 'Start': 0x000F}},
    'STATUS': {'R/W': 'R', 'Register': 0x3000, 'functioncode': 3},
    'OPMODE': {'R/W': 'W', 'Register': 0x3500, 'functioncode': 6, 'Value': {'Position': 1}},
    'VelocityCommand': {'R/W': 'W', 'Register': 0x6F00, 'functioncode': 16},
    'VelocityFeedback': {'R/W': 'R', 'Register': 0x3B00, 'functioncode': 3, 'read_length': 2},
    'PositionCommand': {'R/W': 'W', 'Register': 0x4000, 'functioncode': 16},
    'PositionFeedback': {'R/W': 'R', 'Register': 0x3700, 'functioncode': 3, 'read_length': 2}
}

# Signal handler to ensure clean exit
def signal_handler(sig, frame):
    logger.info("Exiting gracefully...")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Check if serial port is available
if not any(port.device == '/dev/serial0' for port in serial.tools.list_ports.comports()):
    logger.warning("Serial port /dev/serial0 not found. Running in emulated mode.")
    client = None
else:
    # Setup Modbus client
    client = ModbusClient(method='rtu', port='/dev/serial0', baudrate=115200, stopbits=serial.STOPBITS_ONE, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, timeout=1)
    if not client.connect():
        logger.error("Failed to connect to Modbus RTU server.")
        sys.exit(1)

class Servo:
    def __init__(self, client):
        self.client = client

    def read_register(self, register_name):
        register_info = REGISTER_MAP.get(register_name)
        if not register_info:
            raise ValueError(f"Invalid register name: {register_name}")
        if register_info['R/W'] != 'R':
            raise ValueError(f"Register {register_name} is not readable.")
        try:
            response = self.client.read_holding_registers(address=register_info['Register'], count=register_info.get('read_length', 1), unit=1)
            if response.isError():
                raise ModbusIOException("Modbus error")
            return response.registers
        except (ModbusIOException, ModbusSerialException) as e:
            logger.error(f"Error reading register {register_name}: {e}")
            return None

    def write_register(self, register_name, value):
        register_info = REGISTER_MAP.get(register_name)
        if not register_info:
            raise ValueError(f"Invalid register name: {register_name}")
        if register_info['R/W'] != 'W':
            raise ValueError(f"Register {register_name} is not writable.")
        try:
            if register_info['functioncode'] == 6:
                self.client.write_register(address=register_info['Register'], value=value, unit=1)
            elif register_info['functioncode'] == 16:
                self.client.write_registers(address=register_info['Register'], values=[value], unit=1)
            else:
                raise ValueError(f"Unsupported function code: {register_info['functioncode']}")
        except (ModbusIOException, ModbusSerialException) as e:
            logger.error(f"Error writing to register {register_name}: {e}")

# Example usage
if client:
    servo = Servo(client)
    try:
        servo.write_register('CONTROL', REGISTER_MAP['CONTROL']['Value']['Start'])
        time.sleep(1)
        servo.write_register('OPMODE', REGISTER_MAP['OPMODE']['Value']['Position'])
        time.sleep(1)
        servo.write_register('PositionCommand', 1000)
        time.sleep(2)
        position_feedback = servo.read_register('PositionFeedback')
        if position_feedback:
            logger.info(f"Position Feedback: {position_feedback[0]}")
    finally:
        client.close()
else:
    logger.info("Running in emulated mode. No servo operations performed.")

