# Define the GarageDoor class
class GarageDoor:
    def __init__(self, state_pin):
        self.state_pin = state_pin
        self.relay = Relay.one
        self.initialize()

    def initialize(self):
        try:
            AutomationHat.leds.all_off()
            self.relay.off()
            logging.info("Automation HAT initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize Automation HAT: {e}")
            sys.exit(0)

    def read_state(self):
        try:
            state = AutomationHat.inputs[self.state_pin].read()
            if state is None:
                logging.error("Failed to read state pin. Check connection.")
                sys.exit(0)
            return state
        except Exception as e:
            logging.error(f"Error reading state pin: {e}")
            sys.exit(0)

    def trigger(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
            logging.info("Door triggered.")
        except Exception as e:
            logging.error(f"Error triggering door: {e}")
            sys.exit(0)

    @property
    def state(self):
        return "Closed" if self.read_state() == 1 else "Open"

# Signal handler for clean shutdown
