import serial
import minimalmodbus
import signal
import sys
import logging

class ModbusRTUServo:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.instrument = None
        self.logger = logging.getLogger('ModbusRTUServo')
        self.logger.setLevel(logging.DEBUG)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def connect(self):
        try:
            self.instrument = minimalmodbus.Instrument(self.port, self.slave_address)
            self.instrument.serial.baudrate = self.baudrate
            self.instrument.serial.bytesize = serial.EIGHTBITS
            self.instrument.serial.parity = serial.PARITY_NONE
            self.instrument.serial.stopbits = serial.STOPBITS_ONE
            self.instrument.serial.timeout = 1
            self.logger.info("Connected to Modbus RTU servo")
        except serial.SerialException as e:
            self.logger.error(f"Failed to open serial port: {e}")
            sys.exit(1)
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error during connection: {e}")
            sys.exit(1)

    def disconnect(self):
        if self.instrument:
            self.instrument.serial.close()
            self.logger.info("Disconnected from Modbus RTU servo")

    def set_operation_mode(self, mode):
        if not isinstance(mode, int) or mode < 0 or mode > 0xFFFF:
            raise ValueError("Mode must be an integer between 0 and 65535")
        try:
            self.instrument.write_register(0x3500, mode, functioncode=6)
            self.logger.info(f"Set operation mode to {mode}")
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error setting operation mode: {e}")

    def write_position_command(self, value):
        if not isinstance(value, int) or value < 0 or value > 0xFFFF:
            raise ValueError("Value must be an integer between 0 and 65535")
        try:
            self.instrument.write_register(0x4000, value, functioncode=6)
            self.logger.info(f"Set position command to {value}")
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error writing position command: {e}")

    def write_velocity_command(self, value):
        if not isinstance(value, int) or value < 0 or value > 0xFFFF:
            raise ValueError("Value must be an integer between 0 and 65535")
        try:
            self.instrument.write_register(0x6F00, value, functioncode=6)
            self.logger.info(f"Set velocity command to {value}")
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error writing velocity command: {e}")

    def read_position_feedback(self):
        try:
            position = self.instrument.read_registers(0x3700, 2, functioncode=3)
            self.logger.info(f"Read position feedback: {position}")
            return position
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error reading position feedback: {e}")
            return None

    def read_velocity_feedback(self):
        try:
            velocity = self.instrument.read_registers(0x3B00, 2, functioncode=3)
            self.logger.info(f"Read velocity feedback: {velocity}")
            return velocity
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error reading velocity feedback: {e}")
            return None

    def start(self):
        try:
            self.instrument.write_register(0x3100, 0x000F, functioncode=6)
            self.logger.info("Started servo")
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error starting servo: {e}")

    def stop(self):
        try:
            self.instrument.write_register(0x3100, 0x0006, functioncode=6)
            self.logger.info("Stopped servo")
        except minimalmodbus.ModbusException as e:
            self.logger.error(f"Modbus error stopping servo: {e}")

    def read_status(self):
        try:
            status = self.instrument.read_register(0x3000, functioncode=3)
            self.logger.info(f"Read status: {status}")
            return status
        except minimalmodbus.ModbusException as e:
