        aim.close()

import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.ser = None
        self.setup_gpio()
        self.setup_serial()
        self.power_on_module()
        self.verify_module()

    def setup_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.power_pin, GPIO.OUT)

    def setup_serial(self):
        self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)

    def power_on_module(self):
        GPIO.output(self.power_pin, GPIO.HIGH)
        time.sleep(2)
        GPIO.output(self.power_pin, GPIO.LOW)
        time.sleep(3)

    def verify_module(self):
        self.send_command('AT')
        response = self.read_response()
        if response and 'OK' in response:
            print("Module is responsive.")
        else:
            raise Exception("Module is not responsive.")

    def send_command(self, command):
        self.ser.write((command + '\r\n').encode())
        print(f"Sent: {command}")

    def read_response(self, attempts=5):
        response = b''
        for _ in range(attempts):
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting)
                if b'OK' in response or b'ERROR' in response:
                    break
            time.sleep(0.1)
        return response.decode('utf-8', errors='ignore')

    def set_gps_reporting(self, interval_seconds=10):
        self.send_command(f'AT+GPSRD={interval_seconds}')
        response = self.read_response()
        if response and 'OK' in response:
            print(f"GPS reporting set to {interval_seconds} seconds.")
        else:
            raise Exception("Failed to set GPS reporting.")

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        self.send_command(f'AT+CIPSTART="TCP","{ip}",{port}')
        response = self.read_response()
        if response and 'OK' in response:
            print("TCP connection established.")
            self.send_command(f'AT+CIPSEND={len(data)}')
            response = self.read_response()
            if response and '>' in response:
                self.ser.write(data.encode() + b'\x1A')
                response = self.read_response()
                if response and 'SEND OK' in response:
                    print("Data sent successfully.")
                else:
                    raise Exception("Failed to send data.")
            else:
                raise Exception("Failed to enter send mode.")
        else:
            raise Exception("Failed to establish TCP connection.")

    def send_terminator(self):
        self.ser.write(b'\x1A')
        response = self.read_response()
        print(f"Terminator response: {response}")

    def set_message_storage(self, storage='SM'):
        self.send_command(f'AT+CPMS="{storage}","{storage}","{storage}"')
        response = self.read_response()
        if response and 'OK' in response:
            print(f"Message storage set to {storage}.")
        else:
            raise Exception("Failed to set message storage.")

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.ser.close()
        GPIO.cleanup()

def signal_handler(sig, frame):
    print('Exiting gracefully...')
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GSMModule() as gsm:
        gsm.set_gps_reporting()
        gsm.send_tcp_data("Hello, GSM!")
        gsm.send_terminator()
        gsm.set_message_storage()

