import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion
import logging
import time

# Setup logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Keyword classifier
def classify_report(report_text):
    if 'noise' in report_text.lower():
        return 'noise'
    elif 'traffic' in report_text.lower():
        return 'traffic'
    else:
        return 'other'

# MQTT message handler
def handle_message(mqtt_client, userdata, message):
    try:
        report_text = message.payload.decode('utf-8')
        category = classify_report(report_text)
        logger.info(f"Report: {report_text} - Category: {category}")
    except UnicodeDecodeError:
        logger.error("Failed to decode message payload")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")

# Main function
def main():
    client = mqtt.Client(client_id="urban_monitor", protocol=mqtt.MQTTv5)
    client.on_message = handle_message

    try:
        client.connect("localhost", 1883, 60)
        client.subscribe("city/reports", callback=handle_message)
        client.loop_start()

        start_time = time.time()
        while time.time() - start_time < 5:
            time.sleep(0.1)

    except ConnectionRefusedError:
        logger.error("Failed to connect to MQTT broker")
    except Exception as e:
        logger.error(f"Unexpected error: {e}")

    finally:
        client.loop_stop()
        client.disconnect()
        logger.info("MQTT client disconnected gracefully")

if __name__ == "__main__":
    main()

import smbus2
import time

class I2CDevice:
    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus_number = bus_number
        self.bus = smbus2.SMBus(bus_number)
        self._probe_device()

    def _probe_device(self):
        try:
            self.bus.read_byte(self.address)
        except OSError as e:
            raise RuntimeError(f"Device at address {self.address} not found on bus {self.bus_number}") from e

    def write_byte(self, register, value):
        try:
