import smbus2
import time
from datetime import datetime, timezone

class DS1338:
    I2C_ADDRESS = 0x68
    I2C_BUS = 1
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DATE = 0x03
    REG_MONTH = 0x04
    REG_DAY = 0x05
    REG_YEAR = 0x06

    def __init__(self):
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
        except IOError as e:
            raise IOError(f"Failed to open I2C bus {self.I2C_BUS}: {e}")

    def close(self):
        self.bus.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.I2C_ADDRESS, reg)
        except IOError as e:
            raise IOError(f"Failed to read register {reg:02X}: {e}")

    def write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.I2C_ADDRESS, reg, value)
        except IOError as e:
            raise IOError(f"Failed to write register {reg:02X}: {e}")

    def bcd_to_dec(self, bcd):
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    def dec_to_bcd(self, dec):
        return ((dec // 10) << 4) | (dec % 10)

    def read_all(self):
        data = [self.read_register(reg) for reg in range(self.REG_SECONDS, self.REG_YEAR + 1)]
        seconds = self.bcd_to_dec(data[0] & 0x7F)
        hours = self.bcd_to_dec(data[2] & 0x3F)
        return (self.bcd_to_dec(data[6]) + 2000, data[4], data[3], data[5], hours, data[1], seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (1900 <= year <= 2099):
            raise ValueError("Year must be between 1900 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (0 <= day <= 6):
            raise ValueError("Day must be between 0 and 6")
        if not (0 <= hours < 24):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes < 60):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds < 60):
            raise ValueError("Seconds must be between 0 and 59")

        data = [
            self.dec_to_bcd(seconds) & 0x7F,
            self.dec_to_bcd(minutes),
            self.dec_to_bcd(hours) & 0x3F,
            date,
            month,
            day,
            self.dec_to_bcd(year - 2000)
        ]
        for reg, value in enumerate(data):
            self.write_register(self.REG_SECONDS + reg, value)

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.weekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_datetime(datetime.now(timezone.utc))

if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            dt = rtc.read_datetime()
            print(f"Current RTC time: {dt}")
            exit(0)
    except IOError as e:
        import sys
        sys.stderr.write(f"Error: {e}\n")
        exit(1)

