import serial
import signal
import sys
import time

class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.ser = None
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=self.timeout)
        except serial.SerialException as e:
            print(f"Failed to open serial port {self.port}: {e}")
            sys.exit(1)

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        if not self.ser:
            return None
        self.ser.write((command + '\r\n').encode())
        start_time = time.time()
        response = b''
        while time.time() - start_time < timeout:
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting)
                if wait_for in response:
                    return response
        return None

    def test_connection(self):
        return self._send_command('AT') == b'OK'

    def restart(self):
        response = self._send_command('AT+RST', timeout=5.0, wait_for=b'ready')
        if response and b'ready' in response:
            time.sleep(2)
            return self.test_connection()
        return False

    def connect_wifi(self, ssid, password):
        return self._send_command(f'AT+CWJAP="{ssid}","{password}"', timeout=10.0, wait_for=b'OK')

    def disconnect_wifi(self):
        return self._send_command('AT+CWQAP', timeout=1.0, wait_for=b'OK')

    def get_ip(self):
        response = self._send_command('AT+CIFSR', timeout=1.0)
        if response:
            lines = response.decode().split('\r\n')
            for line in lines:
                if 'STAIP' in line:
                    return line.split(':')[1].strip()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if not self._send_command(f'AT+CIPSTART="TCP","{host}",{port}', timeout=5.0, wait_for=b'OK'):
            return None
        request = f"{method} {url} HTTP/1.1\r\nHost: {host}\r\n"
        if headers:
            for header in headers:
                request += f"{header}\r\n"
        request += "\r\n"
        if data:
            request += data
        if not self._send_command(f'AT+CIPSEND={len(request)}', timeout=5.0, wait_for=b'>'):
            return None
        self.ser.write(request.encode())
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        response = b''
        while time.time() - start_time < timeout:
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting)
                if b'+IPD,' in response:
                    parts = response.split(b'+IPD,')
                    if len(parts) > 1:
                        data_part = parts[1].split(b':')
                        if len(data_part) > 1:
                            return data_part[1].split(b'\r\n\r\n')[0]
                if b'CLOSED' in response:
                    return None
        return None

def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    if esp8266.ser:
        esp8266.ser.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    esp8266 = ESP8266Controller()
    if not esp8266.test_connection():
        print("ESP8266 connection test failed.")
        sys.exit(1)
    print("ESP8266 connection test passed.")
    if not esp8266.connect_wifi('your_ssid', 'your_password'):
        print("Failed to connect to Wi-Fi.")
        sys.exit(1)
    print("Connected to Wi-Fi.")
    ip = esp8266.get_ip()
    if ip:
        print(f"IP Address: {ip}")
    else:
        print("Failed to get IP address.")
    response = esp8266.send_http_request('GET', '/', 'example.com')
    if response:
        print(f"HTTP Response: {response.decode()}")
    else:
        print("Failed to send HTTP request.")
    esp8266.disconnect_wifi()
    print("Disconnected from Wi-Fi.")
    esp8266.ser.close()

