    parts = sentence.split(',')
    if len(parts) >= 10 and parts[2] == 'A':
        latitude = float(parts[3])
        latitude_direction = parts[4]
        longitude = float(parts[5])
        longitude_direction = parts[6]
        return latitude, latitude_direction, longitude, longitude_direction
    return None

def convert_to_decimal_degrees(raw_coord, direction):
    degrees = int(raw_coord / 100)
    minutes = raw_coord % 100
    decimal_degrees = degrees + (minutes / 60)
    if direction == 'S' or direction == 'W':
        decimal_degrees = -decimal_degrees
    return decimal_degrees

def main():
    global ser
    ser = serial.Serial('/dev/serial0', 9600, timeout=1)
    signal.signal(signal.SIGINT, signal_handler)

