    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser: Optional[serial.Serial] = None

    def connect(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            self.ser = None

    def disconnect(self):
        if self.ser:
            self.ser.close()
            self.ser = None

    def read_gpgga(self) -> Optional[GPS_readings]:
        if not self.ser:
            return None

        try:
            line = self.ser.readline().decode('utf-8').strip()
        except serial.SerialException as e:
            logging.warning(f"Serial read error: {e}")
            return None

        if not line.startswith('$GPGGA'):
            return None

        fields = line.split(',')
        if len(fields) != 15:
            logging.error(f"Invalid GPGGA sentence: {line}")
            return None

        try:
            latitude = float(fields[2])
            latitude_dir = fields[3]
            longitude = float(fields[4])
            longitude_dir = fields[5]
            altitude = float(fields[9])
            satellite_count = int(fields[7])

            if latitude_dir == 'S':
                latitude = -latitude
            if longitude_dir == 'W':
                longitude = -longitude

            return GPS_readings(latitude, longitude, altitude, satellite_count)
        except ValueError as e:
            logging.error(f"Numeric conversion error in GPGGA sentence: {line}, error: {e}")
            return None

def signal_handler(sig, frame):
    logging.info("Interrupt received, exiting...")
    reader.disconnect()
    sys.exit(0)

