            reading = reader.read_gpgga()
            if reading:
                logging.info(f"GPS Reading: Lat={reading.latitude}, Lon={reading.longitude}, Alt={reading.altitude}, Sat={reading.satellite_count}")
    except KeyboardInterrupt:
        pass
    finally:
        reader.disconnect()

