import serial
import signal
import sys
import time

class ESP8266:
    def __init__(self, port='/dev/ttyS0', baudrate=115200):
        self.port = port
        self.baudrate = baudrate
        self.ser = None
        self._init_serial()

    def _init_serial(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=5, rtscts=True, dsrdtr=True)
            self.ser.flushInput()
            self.ser.flushOutput()
        except serial.SerialException as e:
            print(f"Error opening serial port {self.port}: {e}")
            sys.exit(1)

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.ser.write(command.encode('utf-8'))
            time.sleep(delay)
            response = self._read_response()
            if response in ['OK', 'ERROR', 'FAIL']:
                return response
        return None

    def _read_response(self):
        start_time = time.time()
        response = ''
        while time.time() - start_time < 5:
            if self.ser.in_waiting > 0:
                response += self.ser.read(self.ser.in_waiting).decode('utf-8')
                if 'OK' in response or 'ERROR' in response or 'FAIL' in response:
                    return response.strip()
        return None

    def test_connection(self):
        return self._send_command('AT\r\n') == 'OK'

    def restart(self):
        response = self._send_command('AT+RST\r\n', delay=2)
        return response == 'OK'

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"\r\n'
        response = self._send_command(command, delay=5)
        return 'WIFI GOT IP' in response

    def __del__(self):
        if self.ser:
            self.ser.close()

def signal_handler(sig, frame):
    print('Exiting gracefully...')
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    esp = ESP8266()
    if esp.test_connection():
        print("ESP8266 is connected.")
        if esp.restart():
            print("ESP8266 restarted successfully.")
            if esp.connect_wifi('your_ssid', 'your_password'):
                print("Connected to WiFi successfully.")
            else:
                print("Failed to connect to WiFi.")
        else:
            print("Failed to restart ESP8266.")
    else:
        print("Failed to connect to ESP8266.")

