import serial
import signal
import sys
import time

class GPSController:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        self.port = port
        self.baud = baud
        self.ser = None
        self.open_serial()

    def open_serial(self):
        try:
            self.ser = serial.Serial(self.port, self.baud, timeout=1)
        except serial.SerialException as e:
            raise IOError(f"Failed to open serial port {self.port}: {e}")

    def close(self):
        if self.ser:
            self.ser.close()
            self.ser = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def attach(self):
        self.ser.write(b'AT+CGNSPWR=1\r\n')
        time.sleep(1)
        response = self.ser.readline().decode('utf-8').strip()
        if 'OK' not in response:
            raise IOError(f"Failed to power on GNSS: {response}")

    def detach(self):
        self.ser.write(b'AT+CGNSPWR=0\r\n')
        response = self.ser.readline().decode('utf-8').strip()
        if 'OK' not in response:
            raise IOError(f"Failed to power off GNSS: {response}")

    def get_data(self):
        while True:
            line = self.ser.readline().decode('utf-8').strip()
            if line.startswith('$GPRMC'):
                parts = line.split(',')
                if len(parts) > 2 and parts[2] == 'A':
                    return parts
        return None

def signal_handler(sig, frame):
    print('Received signal, closing GPS controller...')
    gps_controller.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GPSController() as gps_controller:
        gps_controller.attach()
        try:
            while True:
                data = gps_controller.get_data()
                if data:
                    print(f"Received GPS data: {data}")
        except KeyboardInterrupt:
            pass
        finally:
            gps_controller.detach()

