import serial
import threading
from flask import Flask, jsonify, request, abort
from signal import signal, SIGINT, SIGTERM
import sys

app = Flask(__name__)

class SerialCommunicator:
    def __init__(self):
        self.port = None
        self.lock = threading.Lock()

    def open(self, port, baudrate):
        with self.lock:
            try:
                self.port = serial.Serial(port, baudrate, timeout=1)
            except serial.SerialException as e:
                raise e

    def send(self, cmd):
        with self.lock:
            if self.port is None:
                raise serial.SerialException("Port not open")
            self.port.write(cmd.encode('ascii'))
            if self.port.write_size != len(cmd):
                raise serial.SerialException("Failed to write all bytes")
            self.port.flush()

    def receive_line(self):
        with self.lock:
            if self.port is None:
                raise serial.SerialException("Port not open")
            try:
                line = self.port.readline(1024).decode('ascii').strip()
                if not line:
                    return None
                return line
            except serial.SerialException as e:
                raise e

    def close(self):
        with self.lock:
            if self.port:
                self.port.close()
                self.port = None

    def __enter__(self):
        self.open('/dev/ttyUSB0', 9600)
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

serial_comm = SerialCommunicator()

class DataManager:
    def __init__(self):
        self.data = [{'id': 1, 'name': 'Item 1', 'done': False}, {'id': 2, 'name': 'Item 2', 'done': True}]
        self.lock = threading.Lock()

    def get_all(self):
        with self.lock:
            return self.data.copy()

    def get_by_id(self, item_id):
        with self.lock:
            for item in self.data:
                if item['id'] == item_id:
                    return item
            return None

    def create(self, name, done):
        with self.lock:
            if not name or not isinstance(done, bool):
                return False
            new_id = max(item['id'] for item in self.data) + 1
            self.data.append({'id': new_id, 'name': name, 'done': done})
            return True

data_manager = DataManager()

@app.route('/version', methods=['GET'])
def get_version():
    try:
        with serial_comm:
            serial_comm.send('*IDN?\n')
            response = serial_comm.receive_line()
            if response is None:
                return "No response", 504
            return response, 200
    except serial.SerialException as e:
        return str(e), 502

@app.route('/data', methods=['GET'])
def get_data():
    return jsonify(data_manager.get_all())

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    item = data_manager.get_by_id(item_id)
    if item:
        return jsonify(item)
    else:
        abort(404)

@app.route('/data', methods=['POST'])
def create_data():
    data = request.get_json()
    if not data or 'name' not in data or 'done' not in data:
        abort(400)
    if data_manager.create(data['name'], data['done']):
        return jsonify(data_manager.get_by_id(data_manager.data[-1]['id'])), 201
    else:
        abort(400)

def handle_signal(signum, frame):
    serial_comm.close()
    sys.exit(0)

signal(SIGINT, handle_signal)
signal(SIGTERM, handle_signal)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)

