SERIAL_BAUDRATE = 9600

def get_scpi_version():
    try:
        with serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=0.1) as ser:
            ser.write('*IDN?\n'.encode())
            time.sleep(0.1)
            response = ser.read_all().decode().replace('\n', '<br>')
            return response
    except serial.SerialException as e:
        return str(e), 503

